  "Toca para seguir": "Toca per continuar",
  "por": "per",
  "La GTS es un banco online de futbolistas: dejas una copia repetida pidiendo otro futbolista a cambio, y cualquiera que tenga el que pides puede cambiártelo aunque no estés conectado.": "La GTS és un banc en línia de futbolistes: deixes una còpia repetida demanant un altre futbolista a canvi, i qualsevol que tingui el que demanes te'l pot canviar encara que no estiguis connectat.",
  "Para usarla tienes que entrar con tu cuenta.": "Per fer-la servir has d'entrar amb el teu compte.",
  "Ir a Perfil para entrar": "Vés a Perfil per entrar",
  "Recuperar": "Recupera",
  "Dejar un futbolista": "Deixa un futbolista",
  "Solo copias repetidas": "Només còpies repetides",
  "Mejora la «Ventanilla GTS» en Mejoras": "Millora la «Finestreta GTS» a Millores",
  "Huecos: {openLength}/{slots}. La copia que dejas va sin entrenamiento, estrellas ni ascensión: tu futbolista se queda con todo. Un HÉROE ascendido sí puede dejar sus copias repetidas. No se pueden dejar Leyenda ni futbolistas de evento, ni repetir un cambio.": "Espais: {openLength}/{slots}. La còpia que deixes va sense entrenament, estrelles ni ascensió: el teu futbolista ho conserva tot. Un HEROI ascendit sí que pot deixar les seves còpies repetides. No es poden deixar Llegenda ni futbolistes d'esdeveniment, ni repetir un canvi.",
  "Buscar futbolista (el que quieres o el que piden)": "Cerca un futbolista (el que vols o el que demanen)",
  "Solo los que puedo cambiar": "Només els que puc canviar",
