  "Estación Global de Intercambio": "Estació Global d'Intercanvi",
  "Deja una copia repetida, pide el futbolista que te falta y recoge tu cambio cuando vuelvas.": "Deixa una còpia repetida, demana el futbolista que et falta i recull el teu canvi quan tornis.",
  "Ese depósito ya no está: puede que alguien te lo acabe de cambiar.": "Aquest dipòsit ja no hi és: potser algú te l'acaba de canviar.",
