  "Necesitas conexión para reclamar el pase (hora del servidor).": "Necessites connexió per reclamar el passi (hora del servidor).",
  "Cuenta online": "Compte en línia",
  "El servicio online no está activado en esta versión. Tu progreso se guarda en este navegador (Ajustes » Exportar/Importar para llevarlo a otro). Con el servicio activo podrás entrar con Google, reservar tu nombre en todo el mundo, aparecer en el ranking global y guardar en la nube.": "El servei en línia no està activat en aquesta versió. El teu progrés es desa en aquest navegador (Configuració » Exporta/Importa per portar-lo a un altre). Amb el servei actiu podràs entrar amb Google, reservar el teu nom a tot el món, sortir al rànquing global i desar al núvol.",
  "Estás jugando como invitado: tu progreso se guarda solo en este navegador. Entra con Google para reservar tu nombre en todo el mundo, aparecer en el ranking y guardar en la nube. Tu correo es privado: nunca aparece en el ranking.": "Estàs jugant com a convidat: el progrés només es desa en aquest navegador. Entra amb Google per reservar el teu nom a tot el món, sortir al rànquing i desar al núvol. El teu correu és privat: mai no surt al rànquing.",
  "Nombre global: <b>{onlineName}</b> (permanente)": "Nom global: <b>{onlineName}</b> (permanent)",
