  "Las llaves y los niveles son de esta temporada: cuando termine, empieza una nueva con su propio pase. La EXP cuenta aunque no tengas llave: al abrir una fila puedes reclamar todo lo que ya hayas alcanzado.": "Les claus i els nivells són d'aquesta temporada: quan acabi, en comença una de nova amb el seu propi passi. L'EXP compta encara que no tinguis clau: en obrir una fila pots reclamar tot el que ja hagis assolit.",
