  "Tienes <b>5 equipos</b>: cambia entre ellos arriba. Elige <b>7 candidatos</b>. Empiezas solo con el <b>capitán</b>; al subir de nivel podrás fichar a los otros seis (máximo {MAX_TEAM} en el campo). Pulsa un futbolista de tu colección para añadirlo o quitarlo, pulsa una plaza para cambiarla, o arrastra para colocar e intercambiar. Se guarda solo.": "Tens <b>5 equips</b>: canvia entre ells a dalt. Tria <b>7 candidats</b>. Comences només amb el <b>capità</b>; en pujar de nivell podràs fitxar els altres sis (màxim {MAX_TEAM} al camp). Prem un futbolista de la teva col·lecció per afegir-lo o treure'l, prem una plaça per canviar-la, o arrossega per col·locar i intercanviar. Es desa sol.",
