  "Elige el uniforme de tu escuadra: cambia el cuerpo y conserva la cabeza original y todas las animaciones. Se consiguen con las recompensas de equipo de la Enciclopedia.": "Tria l'uniforme del teu esquadró: canvia el cos i conserva el cap original i totes les animacions. S'aconsegueixen amb les recompenses d'equip de l'Enciclopèdia.",
