  "Devolver puntos": "Retorna punts",
  "Cada ficha suma 1 punto a la estadística que elijas (máximo {tmax} para este futbolista). Se ganan con victorias, rangos superados, supervivencia infinita, misiones semanales y logros.": "Cada fitxa suma 1 punt a l'estadística que triïs (màxim {tmax} per a aquest futbolista). Es guanyen amb victòries, rangs superats, supervivència infinita, missions setmanals i èxits.",
