  "(adaptación de InaZurvivors)": "(adaptació d'InaZurvivors)",
  "Talento:": "Talent:",
  "(efecto adaptado; sube con el nivel de la técnica)": "(efecte adaptat; puja amb el nivell de la tècnica)",
  "Repertorio (2 técnicas activas en combate)": "Repertori (2 tècniques actives en combat)",
  "☆ Empezar con esta": "☆ Comença amb aquesta",
  "✦ Ver su Aura": "✦ Mira la seva Aura",
  "{add} Aura": "{add} Aura",
  "Valores centrados en 60: por encima suman, por debajo restan. Cada técnica usa las estadísticas de su futbolista. Lo propio llega a 99; con un Aura, hasta {EFFECTIVE_STAT_MAX}.": "Valors centrats en 60: per sobre sumen, per sota resten. Cada tècnica fa servir les estadístiques del seu futbolista. El propi arriba a 99; amb una Aura, fins a {EFFECTIVE_STAT_MAX}.",
  "Banner de agradecimiento": "Bàner d'agraïment",
  "Ataque a los Titanes, Los Siete Pecados Capitales y Axel Encapuchado · {cost} fichas de evento la tirada": "L'Atac dels Titans, Els Set Pecats Capitals i Axel Encaputxat · {cost} fitxes d'esdeveniment la tirada",
