  "NUEVO": "NOU",
  ": se desbloquea para siempre y ya puede ir en Mi Equipo.": ": es desbloqueja per sempre i ja pot anar a El meu equip.",
  "Duplicado": "Duplicat",
  ": sirve para ascender al futbolista; si ya no puede ascender más, se convierte en monedas.": ": serveix per ascendir el futbolista; si ja no pot ascendir més, es converteix en monedes.",
  "Los duplicados también pagan la <b>ascensión</b> de cualquier futbolista (Fix 1.53): cada ascensión sube una rareza y cuesta según la rareza desde la que sube (Común {ascenso}, Raro {ascenso2}, Épico {ascenso3}, Legendario {ascenso4}). Al llegar a Mítico, el HÉROE cuesta según la rareza con la que nació: Común {heroe}, Raro {heroe2}, Épico {heroe3}, Legendario {heroe4}, Mítico {heroe5} y Leyenda {heroe6}. Después, cada HÉROE gana hasta {HERO_STARS_MAX} estrellas de héroe (Mítico {estrella} duplicados cada una).": "Els duplicats també paguen l'<b>ascensió</b> de qualsevol futbolista (Fix 1.53): cada ascensió puja una raresa i costa segons la raresa des de la qual puja (Comú {ascenso}, Rar {ascenso2}, Èpic {ascenso3}, Llegendari {ascenso4}). En arribar a Mític, l'HEROI costa segons la raresa amb què va néixer: Comú {heroe}, Rar {heroe2}, Èpic {heroe3}, Llegendari {heroe4}, Mític {heroe5} i Llegenda {heroe6}. Després, cada HEROI guanya fins a {HERO_STARS_MAX} estrelles d'heroi (Mític {estrella} duplicats cadascuna).",
  "Con {MAX_STARS} estrellas y HÉROE, cada copia da monedas (de {comun} a {leyenda} según la rareza).": "Amb {MAX_STARS} estrelles i HEROI, cada còpia dona monedes (de {comun} a {leyenda} segons la raresa).",
  "Fichas = máquina de cápsulas · Monedas = mejoras y tiendas. Gráficos de la máquina: Inazuma Eleven 3 (hoja de The Spriters Resource, ripeada por Avegaille), recurso local.": "Fitxes = màquina de càpsules · Monedes = millores i botigues. Gràfics de la màquina: Inazuma Eleven 3 (full de The Spriters Resource, ripejat per Avegaille), recurs local.",
  "Duplicado · +{refund} monedas": "Duplicat · +{refund} monedes",
