  "Por comprar": "Per comprar",
  "REPERTORIO": "REPERTORI",
  "Cada futbolista solo usa su propio repertorio. Aquí desbloqueas sus técnicas y compras <b>manuales</b> de daño permanente (subir de nivel una técnica en partida es aparte).": "Cada futbolista només fa servir el seu propi repertori. Aquí desbloqueges les seves tècniques i compres <b>manuals</b> de dany permanent (pujar de nivell una tècnica a la partida és a part).",
  "Bonificaciones para todo el equipo. No cambian la equipación Raimon que se ve en combate.": "Bonificacions per a tot l'equip. No canvien l'equipació Raimon que es veu en combat.",
  "InaZurvivors — Proyecto de fans no oficial": "InaZurvivors — Projecte de fans no oficial",
  "InaZurvivors es un fangame independiente y gratuito desarrollado por AstraStorm17, inspirado en la franquicia Inazuma Eleven.": "InaZurvivors és un fangame independent i gratuït desenvolupat per AstraStorm17, inspirat en la franquícia Inazuma Eleven.",
  "Inazuma Eleven, sus personajes, nombres, diseños, logotipos, música y materiales originales son propiedad de LEVEL-5 y/o sus respectivos titulares.": "Inazuma Eleven, els seus personatges, noms, dissenys, logotips, música i materials originals són propietat de LEVEL-5 i/o dels seus respectius titulars.",
  "Este proyecto no está afiliado, patrocinado ni aprobado por LEVEL-5.": "Aquest projecte no està afiliat, patrocinat ni aprovat per LEVEL-5.",
  "El código y los materiales originales desarrollados específicamente para InaZurvivors pertenecen a sus respectivos autores.": "El codi i els materials originals desenvolupats específicament per a InaZurvivors pertanyen als seus respectius autors.",
  "Los recursos gráficos y sonoros de terceros conservan sus derechos originales.": "Els recursos gràfics i sonors de tercers conserven els seus drets originals.",
  "La inclusión de créditos y este aviso no implica la existencia de una licencia o autorización para distribuir material protegido.": "La inclusió de crèdits i aquest avís no implica l'existència d'una llicència o autorització per distribuir material protegit.",
  "Desarrollo": "Desenvolupament",
  "Diseño, dirección y desarrollo: AstraStorm17.": "Disseny, direcció i desenvolupament: AstraStorm17.",
  "Programación con asistencia de Claude (Anthropic).": "Programació amb l'assistència de Claude (Anthropic).",
  "Recursos de terceros y su procedencia": "Recursos de tercers i la seva procedència",
  "Futbolistas, retratos, cuerpos, escudos, objetos, arenas y música: Inazuma Eleven 2 (LEVEL-5), extraídos de una copia propia del juego.": "Futbolistes, retrats, cossos, escuts, objectes, arenes i música: Inazuma Eleven 2 (LEVEL-5), extrets d'una còpia pròpia del joc.",
  "Futbolistas, retratos y escudos de las sagas Mundial, GO, Chrono Stones, Galaxy, Ares y Orion: Inazuma Eleven 3 (LEVEL-5) con el parche de fans «Great Road of Heroes 3.1». Autoría del parche: no verificada; base y añadidos del parche no se pueden separar.": "Futbolistes, retrats i escuts de les sagues Mundial, GO, Chrono Stones, Galaxy, Ares i Orion: Inazuma Eleven 3 (LEVEL-5) amb el pedaç de fans «Great Road of Heroes 3.1». Autoria del pedaç: no verificada; la base i els afegits del pedaç no es poden separar.",
  "Creados para InaZurvivors: efectos de supertécnicas, efectos de sonido, iconos de elemento, orbes, música «Generada» e interfaz.": "Creats per a InaZurvivors: efectes de supertècniques, efectes de so, icones d'element, orbes, música «Generada» i interfície.",
  "Redes sociales": "Xarxes socials",
  "Sobre el desarrollador": "Sobre el desenvolupador",
  "AstraStorm también ha creado otros videojuegos.": "AstraStorm també ha creat altres videojocs.",
  "Enlaces oficiales": "Enllaços oficials",
  "Sin cuenta, InaZurvivors no recopila datos personales: tu progreso se guarda solo en este navegador. Con cuenta online (Google) se guardan tu correo de Google (privado), tu nombre, tus marcas y tu guardado.": "Sense compte, InaZurvivors no recull dades personals: el teu progrés només es desa en aquest navegador. Amb compte en línia (Google) es desen el teu correu de Google (privat), el teu nom, les teves marques i el teu desament.",
  "{VERSION_LABEL} · compilación interna {BUILD}": "{VERSION_LABEL} · compilació interna {BUILD}",
