  "Con la sesión iniciada, cada partida en solitario se graba (posiciones, técnicas y cartas, sin nada personal) para que el autor vea cómo se juega y equilibre el juego. Se guardan tus 3 últimas y las de tus marcas del ranking.": "Amb la sessió iniciada, cada partida en solitari es grava (posicions, tècniques i cartes, res personal) perquè l'autor vegi com es juga i equilibri el joc. Es desen les teves 3 últimes i les de les teves marques del rànquing.",
