  "{active}/{TRAIN_SLOTS} técnicas activas": "{active}/{TRAIN_SLOTS} tècniques actives",
  "Prueba las técnicas de tus futbolistas al nivel que quieras, también las combinadas que puedan hacer juntos (con sus Auras incluidas). Nadie recibe daño y no se gana nada: ni recompensas, ni misiones, ni ranking.": "Prova les tècniques dels teus futbolistes al nivell que vulguis, també les combinades que puguin fer junts (amb les seves Aures incloses). Ningú no rep dany i no es guanya res: ni recompenses, ni missions, ni rànquing.",
