  "CONTINUAR SOBREVIVIENDO": "CONTINUA SOBREVIVINT",
  "Cinco fases hasta el Infierno. Cada minuto jugado da recompensa y los jefes regresan.": "Cinc fases fins a l'Infern. Cada minut jugat dona recompensa i els caps tornen.",
  "Nv {from} → Nv {to}": "Nv {from} → Nv {to}",
  "✖ ALTAR DE DESPIDO": "✖ ALTAR D'ACOMIADAMENT",
  "Elige a quién echas del equipo. Pierdes sus técnicas y su parte de la vida, y su hueco queda libre para otro fichaje. El capitán no se puede echar.": "Tria qui fas fora de l'equip. Perds les seves tècniques i la seva part de la vida, i el seu lloc queda lliure per a un altre fitxatge. El capità no es pot fer fora.",
