  "Sin decreto, pero el Sector envía a sus SEED: rivales +{x1} % de vida y muchos más SEED. Puntos ×{x2}.": "Sense decret, però el Sector envia els seus SEED: rivals +{x1} % de vida i molts més SEED. Punts ×{x2}.",
  "Esta semana gana {otherName}": "Aquesta setmana guanya {otherName}",
