  " +1 copia": " +1 còpia",
  "DECRETO DE LA SEMANA {x1} · SE CUENTA EN {x2}": "DECRET DE LA SETMANA {x1} · ES COMPTA EN {x2}",
  "{x1} <b>{x2}</b> · suma ganando partidas (rebelarte da ×{x3})": "{x1} <b>{x2}</b> · suma guanyant partides (rebel·lar-te dona ×{x3})",
  "{tokens} fichas · {x1} ◉ · una copia de sus tres estrellas · el marco del bando (la primera vez)": "{tokens} fitxes · {x1} ◉ · una còpia de les seves tres estrelles · el marc del bàndol (la primera vegada)",
  "{tokens} fichas · {x1} ◉ si jugaste esa semana": "{tokens} fitxes · {x1} ◉ si vas jugar aquella setmana",
  "Semana {x1}": "Setmana {x1}",
  "{x1}El bando es para toda la temporada y no se puede cambiar. Para que la lucha sea justa, el bando que vaya por delante en miembros no admite a nadie más hasta que el otro lo alcance. Cuentan las victorias de partidas normales (sin cooperativo, Road, clan ni entrenamiento).": "{x1}El bàndol és per a tota la temporada i no es pot canviar. Perquè la lluita sigui justa, el bàndol que vagi per davant en membres no admet ningú més fins que l'altre l'atrapi. Compten les victòries de partides normals (sense cooperatiu, Road, clan ni entrenament).",
  "Road to Fútbol Frontier: ahora Jaden sale a las 3 victorias en Máxima y otra copia cada 3. Por tus victorias recibes {x1}.": "Road to Fútbol Frontier: ara Jaden surt a les 3 victòries a Màxima i una altra còpia cada 3. Per les teves victòries reps {x1}.",
  "{x1} repeticiones borradas": "{x1} repeticions esborrades",
  "{rowsLength} repeticiones · {x1} en total. Cada jugador guarda sus 3 últimas y las de sus marcas del ranking.": "{rowsLength} repeticions · {x1} en total. Cada jugador conserva les seves 3 últimes i les de les seves marques del rànquing.",
