  "Sin vínculo especial con {pName}. Un compañero de historia, familia o técnica conjunta daría {x1}%.": "Sense vincle especial amb {pName}. Un company d'història, família o tècnica conjunta donaria {x1}%.",
  "Bonificación = estadística del Aura × {x1}%, redondeada. Lo propio sigue en 99 como máximo; con el Aura, hasta {EFFECTIVE_STAT_MAX}.": "Bonificació = estadística de l'Aura × {x1}%, arrodonida. El propi continua en 99 com a màxim; amb l'Aura, fins a {EFFECTIVE_STAT_MAX}.",
  "{x1} · {x2} · poder {power}": "{x1} · {x2} · poder {power}",
  "La primera empieza la partida en una ranura extra de Aura; la segunda puede aprenderse al subir de nivel. Golpean al {x1}% (son una técnica activa de más). No sustituyen a las suyas y desaparecen si quitas el Aura.": "La primera comença la partida en una ranura extra d'Aura; la segona es pot aprendre en pujar de nivell. Colpegen al {x1}% (són una tècnica activa de més). No substitueixen les seves i desapareixen si treus l'Aura.",
  "{x1} Afinidad de {x2}": "{x1} Afinitat de {x2}",
  "Las técnicas de {pName} de elemento {x1} (también las heredadas) hacen <b>+{x2}%</b> de daño. {pName} sigue siendo de {x3} para todo lo demás.": "Les tècniques de {pName} d'element {x1} (també les heretades) fan <b>+{x2}%</b> de dany. {pName} continua sent de {x3} per a tota la resta.",
