  "{x1} <b>{x2}</b>, y si llevas {min} o más jugadores de ese equipo en el campo, «Química de club»: +{x3}% de daño.": "{x1} <b>{x2}</b>, i si portes {min} o més jugadors d'aquest equip al camp, «Química de club»: +{x3}% de dany.",
