  "{x1} <b>{stars}/{MAX_STARS}</b>{x2} · daño ×{toFixed} · vida ×{toFixed2} · duplicados libres {sparesOf}": "{x1} <b>{stars}/{MAX_STARS}</b>{x2} · dany ×{toFixed} · vida ×{toFixed2} · duplicats lliures {sparesOf}",
  "✦ Elige {x1} de límite (+{STAR_CAP_STEP})": "✦ Tria {x1} de límit (+{STAR_CAP_STEP})",
  "Toca una estadística por cada estrella: su límite sube +{STAR_CAP_STEP}. Puedes repetir la misma.{x1}": "Toca una estadística per cada estrella: el seu límit puja +{STAR_CAP_STEP}. Pots repetir la mateixa.{x1}",
