  "COLABORACIÓN · TERMINA EN {x1}": "COL·LABORACIÓ · ACABA EN {x1}",
  "★ Destacada hoy: Épico ×{x1} · Legendario, Mítico y Leyenda ×{x2}": "★ Destacada avui: Èpic ×{x1} · Llegendari, Mític i Llegenda ×{x2}",
  "{x1}Precio y reglas": "{x1}Preu i regles",
  "Los futbolistas especiales solo salen aquí, con {x1} Comunes, Raros y Épicos de relleno. Se paga con fichas de evento: cada partida en Rango S o X te da tantas como fichas normales mientras dura el evento.": "Els futbolistes especials només surten aquí, amb {x1} Comuns, Rars i Èpics de farciment. Es paga amb fitxes d'esdeveniment: cada partida en Rang S o X te'n dona tantes com fitxes normals mentre dura l'esdeveniment.",
  "{x1}Tus {unit}": "{x1}Les teves {unit}",
  "{x1} <b>{PULL_COST}</b> {x2} <b>{MULTI_COST}</b> {x3} <b>{HUNDRED_COST}</b> (diez ×10 de golpe, un Épico o mejor asegurado en cada diez). {x4}{x5}": "{x1} <b>{PULL_COST}</b> {x2} <b>{MULTI_COST}</b> {x3} <b>{HUNDRED_COST}</b> (deu ×10 de cop, un Èpic o millor assegurat a cada deu). {x4}{x5}",
  "Te llega para {x1} tirada(s).": "Tens per a {x1} tirada(es).",
  "{x1}Cómo conseguir fichas": "{x1}Com aconseguir fitxes",
  "{x1}Nuevo, duplicado y ascensión": "{x1}Nou, duplicat i ascensió",
  "(hasta {MAX_STARS}): se compran con monedas en su ficha (10.000, 20.000… 50.000). Cada una da +{x1}% daño, +{x2}% vida y +5 al límite de la estadística que elijas. Los HÉROES y Campeones tienen 3 estrellas extra (100.000, 110.000 y 120.000).": "(fins a {MAX_STARS}): es compren amb monedes a la seva fitxa (10.000, 20.000… 50.000). Cadascuna dona +{x1}% de dany, +{x2}% de vida i +5 al límit de l'estadística que triïs. Els HEROIS i Campions tenen 3 estrelles extra (100.000, 110.000 i 120.000).",
  "{x1}Probabilidades": "{x1}Probabilitats",
  "{x1}: sin futbolistas por ahora; su probabilidad pasa a la rareza inferior.": "{x1}: sense futbolistes de moment; la seva probabilitat passa a la raresa inferior.",
