  "Aparece sola en partida a partir del nivel {x1}; comprándola, desde el 1.": "Apareix sola a la partida a partir del nivell {x1}; si la compres, des de l'1.",
  "{x1}Tu plantilla": "{x1}La teva plantilla",
  "{x1} · {techniquesLength} técnicas": "{x1} · {techniquesLength} tècniques",
  "Máquina de cápsulas: gráficos de Inazuma Eleven 3 (LEVEL-5), hoja publicada en {x1}, ripeada por Avegaille.": "Màquina de càpsules: gràfics d'Inazuma Eleven 3 (LEVEL-5), full publicat a {x1}, ripejat per Avegaille.",
  "Nombres en español e inglés de parte de las técnicas: {x1} (Fandom), contenido bajo {x2}.": "Noms en castellà i anglès de part de les tècniques: {x1} (Fandom), contingut sota {x2}.",
  "Motor: {x1} © Richard Davey, Phaser Studio Inc. ({x2}). Herramienta: {x3} (MIT).": "Motor: {x1} © Richard Davey, Phaser Studio Inc. ({x2}). Eina: {x3} (MIT).",
  "Fuente: Press Start 2P © The Press Start 2P Project Authors ({x1}), vía Fontsource.": "Font: Press Start 2P © The Press Start 2P Project Authors ({x1}), via Fontsource.",
  "Ahora suena: {x1}. Por defecto suena la música de Inazuma Eleven exportada de tu copia. «Generada» usa temas creados para este proyecto.": "Ara sona: {x1}. Per defecte sona la música d'Inazuma Eleven exportada de la teva còpia. «Generada» fa servir temes creats per a aquest projecte.",
  "Vuelves a empezar como un jugador nuevo{x1}. No es lo mismo que eliminar la cuenta.": "Tornes a començar com un jugador nou{x1}. No és el mateix que eliminar el compte.",
