  "★ ACTIVO · Definitiva": "★ ACTIU · Definitiva",
  "con R": "amb R",
  "Capitán: <b>{capName}</b>": "Capità: <b>{capName}</b>",
  "Esperando a que <b>{partner}</b> elija la arena y empiece…": "Esperant que <b>{partner}</b> triï l'arena i comenci…",
  "Mis depósitos": "Els meus dipòsits",
  ": otro dispositivo guardó una versión más nueva": ": un altre dispositiu ha desat una versió més nova",
  "Próximo gran premio: <b>{label}</b> · nivel {x1} {x2} · faltan {x3}": "Proper gran premi: <b>{label}</b> · nivell {x1} {x2} · falten {x3}",
  "Ver el Sector": "Mira el Sector",
  "El fútbol necesita orden. A partir de hoy, el Sector Quinto decide cómo se juega cada partido.": "El futbol necessita ordre. A partir d'avui, el Sector Cinquè decideix com es juga cada partit.",
  "Únete a nosotros… o intenta resistir. Cada semana veremos qué bando juega mejor.": "Uneix-te a nosaltres… o intenta resistir. Cada setmana veurem quin bàndol juga millor.",
  "Bienvenido al Sector Quinto. Aquí el fútbol se juega como yo digo.": "Benvingut al Sector Cinquè. Aquí el futbol es juga com dic jo.",
  "Acata mis decretos y tu bando ganará.": "Acata els meus decrets i el teu bàndol guanyarà.",
  "La Resistencia… Veremos cuánto aguanta vuestro viento.": "La Resistència… Veurem quant aguanta el vostre vent.",
  "Rebélate si quieres: el Sector Quinto también sabe jugar duro.": "Rebel·la't si vols: el Sector Cinquè també sap jugar dur.",
  "¡Llega {eName}!": "Arriba {eName}!",
  "{x1} · {x2} rivales · Nv {level}": "{x1} · {x2} rivals · Nv {level}",
  "sus estadísticas (Aura legendaria)": "les seves estadístiques (Aura llegendària)",
  "Cada plaza de tu equipo tiene ahora una <b>{x1}</b> {x2} <b>{x3}</b>. Ahí pones a otro futbolista de tu colección para que apoye al de la plaza. El Aura no juega: lo potencia.": "Cada plaça del teu equip té ara una <b>{x1}</b> {x2} <b>{x3}</b>. Allà hi poses un altre futbolista de la teva col·lecció perquè doni suport al de la plaça. L'Aura no juga: el potencia.",
  "Solo pueden ser Aura los <b>Legendarios, Míticos y Leyendas</b>.": "Només poden ser Aura els <b>Llegendaris, Mítics i Llegendes</b>.",
  "Una por futbolista. No se gasta nada: tu colección no cambia.": "Una per futbolista. No es gasta res: la teva col·lecció no canvia.",
  "El Aura suma el <b>{x1}%</b> {x2} <b>{x3}</b> a las mismas del portador.": "L'Aura suma el <b>{x1}%</b> {x2} <b>{x3}</b> a les mateixes del portador.",
  "Ejemplo: Tiro 90 + Aura con Tiro 95 » 90 + 14 = <b>104</b>.": "Exemple: Tir 90 + Aura amb Tir 95 » 90 + 14 = <b>104</b>.",
  "Lo propio sigue en 99 como máximo; con el Aura, hasta <b>120</b>, y en el combate se nota.": "El propi continua en 99 com a màxim; amb l'Aura, fins a <b>120</b>, i en el combat es nota.",
  "En el radar, lo que aporta el Aura se ve en <b style=\"color:#7ff6ff\">cian</b>.": "Al radar, el que aporta l'Aura es veu en <b style=\"color:#7ff6ff\">cian</b>.",
  "Si los dos tienen historia (técnica conjunta, amistad, familia o rivalidad), el Aura da el <b>{x1}%</b>{x2} <b>♥</b>.": "Si tots dos tenen història (tècnica conjunta, amistat, família o rivalitat), l'Aura dona el <b>{x1}%</b>{x2} <b>♥</b>.",
