  "LA GACETA {x1}": "LA GASETA {x1}",
  "Versión de pruebas del cooperativo: puede fallar. Tu partida es la misma que en la web normal.": "Versió de proves del cooperatiu: pot fallar. La teva partida és la mateixa que a la web normal.",
  "PRUEBAS · pre-2.0": "PROVES · pre-2.0",
  "Cargando futbolistas…": "Carregant futbolistes…",
  "No se pudieron cargar los datos del juego. Si el problema sigue, esta versión puede no incluir sus recursos.": "No s'han pogut carregar les dades del joc. Si el problema continua, és possible que aquesta versió no inclogui els seus recursos.",
  "Preparando caras y objetos…": "Preparant cares i objectes…",
  "Abriendo el vestuario…": "Obrint el vestidor…",
  "¡Listo!": "Som-hi!",
  "InaZurvivors 2.3 — Ya en inglés": "InaZurvivors 2.3 — Ja en anglès",
  "InaZurvivors, now in English": "InaZurvivors, now in English",
  "El juego entero se puede jugar en inglés: menús, partidas, datos, noticias y todo el historial de versiones. Si tu navegador está en inglés se abre solo en inglés; si no, sigue en español.": "Tot el joc es pot jugar en anglès: menús, partides, dades, notícies i tot l'historial de versions. Si el teu navegador està en anglès s'obre directament en anglès; si no, continua en castellà.",
  "Español o inglés": "Castellà o anglès",
  "Elige el idioma en Ajustes > Idioma, o déjalo en «Automático» para que siga al navegador. Al cambiarlo, el juego se recarga en el idioma nuevo y tu partida no cambia.": "Tria l'idioma a Configuració > Idioma, o deixa'l en «Automàtic» perquè segueixi el navegador. En canviar-lo, el joc es recarrega en l'idioma nou i la teva partida no canvia.",
  "Nombres oficiales": "Noms oficials",
  "En inglés, las supertécnicas y las técnicas combinadas llevan su nombre del doblaje oficial (Fire Tornado, God Hand, Crossfire…), y los elementos son Fire, Wind, Wood y Earth.": "En anglès, les supertècniques i les tècniques combinades porten el seu nom del doblatge oficial (Fire Tornado, God Hand, Crossfire…), i els elements són Fire, Wind, Wood i Earth.",
  "Noticias en los dos idiomas": "Notícies en els dos idiomes",
  "Las noticias y todas las versiones desde la v1.0 se pueden leer en inglés.": "Les notícies i totes les versions des de la v1.0 es poden llegir en anglès.",
  "Números a su manera": "Números a la seva manera",
  "En inglés, las cifras y las fechas salen con el formato inglés (1,000 monedas, 0.5 %).": "En anglès, les xifres i les dates surten amb el format anglès (1,000 monedes, 0.5 %).",
  "Abre Ajustes y mira la nueva opción Idioma.": "Obre Configuració i mira la nova opció Idioma.",
  "Pásale el juego a tus amigos que no hablan español.": "Passa el joc als teus amics que no parlen castellà.",
  "Muévete con el joystick y acércate a alguien para ver su ficha; tócala para abrir su perfil.": "Mou-te amb el joystick i acosta't a algú per veure la seva fitxa; toca-la per obrir-ne el perfil.",
  "Muévete con WASD o flechas y pasa el ratón por encima de alguien para ver su ficha; haz clic para abrir su perfil.": "Mou-te amb WASD o fletxes i passa el ratolí per sobre d'algú per veure la seva fitxa; fes clic per obrir-ne el perfil.",
  "Top 3": "Top 3",
  "♥ AMIGO": "♥ AMIC",
  "Equipación: {x1}": "Equipació: {x1}",
  "Toca para ver su perfil": "Toca per veure'n el perfil",
  "Clic para ver su perfil": "Clic per veure'n el perfil",
  "Sala de jugadores renovada": "Sala de jugadors renovada",
  "Cada jugador lleva su equipación, tus amigos salen en verde, el top 3 con su corona y, sobre el nombre, el escudo de su clan y su bando. Haz clic (o toca su ficha) para abrir su perfil.": "Cada jugador porta la seva equipació, els teus amics surten en verd, el top 3 amb la seva corona i, sobre el nom, l'escut del seu clan i el seu bàndol. Fes clic (o toca la seva fitxa) per obrir-ne el perfil.",
  "¿Padre e hijo? Jaden lleva el apellido de Mark adulto y juega con su mismo corazón. Nadie lo ha confirmado.": "Pare i fill? En Jaden porta el cognom d'en Mark adult i juga amb el seu mateix cor. Ningú no ho ha confirmat.",
  "Los Evans: el cuaderno de entrenamiento de David llega hasta Jaden.": "Els Evans: el quadern d'entrenament d'en David arriba fins a en Jaden.",
  "Silvia lo cuida como cuidó al Raimon de Mark… y dicen que Jaden tiene su misma mirada. ¿Será su madre?": "La Silvia el cuida com va cuidar el Raimon d'en Mark… i diuen que en Jaden té la seva mateixa mirada. Serà la seva mare?",
  "Vibración (móvil)": "Vibració (mòbil)",
  "Activada": "Activada",
  "Desactivada": "Desactivada",
  "Más vivo en el móvil": "Més viu al mòbil",
  "El móvil vibra al recibir un golpe, al subir de nivel, con las definitivas, al llegar el jefe y al fichar un Legendario o mejor (se quita en Ajustes). Los botones responden al tocarlos y los avisos ya no tapan la partida.": "El mòbil vibra en rebre un cop, en pujar de nivell, amb les definitives, quan arriba el cap i en fitxar un Llegendari o millor (es treu a Configuració). Els botons responen en tocar-los i els avisos ja no tapen la partida.",
  "la Llave dorada del pase": "la Clau daurada del passi",
  "{n} futbolistas": "{n} futbolistes",
  "Creadores de contenido: banner y marco propios, 1.500 fichas de colaboración, 3.000 fichas, la Llave dorada, los 7 del Banner de agradecimiento, 300.000 monedas y 9 Fichas EG": "Creadors de contingut: bàner i marc propis, 1.500 fitxes de col·laboració, 3.000 fitxes, la Clau daurada, els 7 del Bàner d'agraïment, 300.000 monedes i 9 Fitxes EG",
  "Creador de contenido": "Creador de contingut",
  "Código de creadores de contenido": "Codi de creadors de contingut",
  "Grabas, editas y subes: InaZurvivors llega más lejos gracias a ti.": "Graves, edites i penges: InaZurvivors arriba més lluny gràcies a tu.",
  "Marco de Creador": "Marc de Creador",
  "Un botón de play con alas: el marco de quien graba InaZurvivors.": "Un botó de play amb ales: el marc de qui grava InaZurvivors.",
  "Tu última partida se cortó a los {x1}: aquí tienes lo que llevabas ganado.": "La teva última partida es va tallar als {x1}: aquí tens el que portaves guanyat.",
  "Teclados AZERTY": "Teclats AZERTY",
  "El movimiento va por la posición de las teclas y no por la letra: en un teclado francés te mueves con ZQSD.": "El moviment va per la posició de les tecles i no per la lletra: en un teclat francès et mous amb ZQSD.",
  "¡RÉCORD!": "RÈCORD!",
  "Eliminaciones": "Eliminacions",
  "Nivel": "Nivell",
  "Minijefes": "Minicaps",
  "Supervivencia ({x1} s)": "Supervivència ({x1} s)",
  "Minijefes ({x1})": "Minicaps ({x1})",
  "**{title}**: {text}": "**{title}**: {text}",
  "Tienda · {x1} ◉": "Botiga · {x1} ◉",
  "Logro: {how}": "Èxit: {how}",
  "Código": "Codi",
  " (¡nuevo!)": " (nou!)",
  "★ Ver {x1}": "★ Mira {x1}",
  "{x1}% · c/u {x2}%": "{x1}% · c/u {x2}%",
  "vacía": "buida",
